  return {
    accepted: true,
    value: {
      ...candidate.value,
      verificationStatus: fact.verificationStatus,
      acceptedAt: fact.acceptedAt,
      promotion: sanitizeRuntimeMemoryFactPromotionEvidence(fact.promotion),
