{"edits":[{"path":"openclaw_runtime/src/runtime-core/memory-effect-receipt.ts","content":"import type { RuntimeCoreJsonObject } from "./types.js";

/** The three outcomes defined by RC-04 for an externally visible effect. */
export type MemoryEffectOutcome = "applied" | "not_applied" | "unknown";

export type MemoryEffectAction =
  | "memory_update"
  | "memory_forget"
  | "memory_strengthen";

export type MemoryEffectActor = {
  sessionKey: string;
  runId: string;
  attemptIndex: number;
  modelCallIndex: number;
};

export type MemoryEffectDescriptor = {
  toolCallId: string;
  toolName: string;
  resource: string;
  action: string;
};

/**
 * The proposal is deliberately an identifier envelope. Memory text and the
 * other facts supplied to a self-edit tool must never be copied into an
 * effect receipt.
 */
export type MemoryEffectProposal = {
  domain: "runtime_memory";
  action: MemoryEffectAction;
  factId: string;
  newFactId?: string;
};

export type MemoryEffectStage1Context = {
  actor: MemoryEffectActor;
  effect: MemoryEffectDescriptor;
};

export type MemoryEffectReceipt = {
  schemaVersion: 1;
  effectId: string;
  requestId: string;
  actor: MemoryEffectActor;
  domain: "runtime_memory";
  action: MemoryEffectAction;
  proposal: MemoryEffectProposal;
  stage1Context: MemoryEffectStage1Context;
  outcome: MemoryEffectOutcome;
  idempotencyKey: string;
  createdAt: number;
};

export type EffectReceiptAppendResult =
  | { status: "applied"; duplicate: false }
  | { status: "duplicate"; duplicate: true }
  | { status: "conflict"; duplicate: false }
  | { status: "rejected"; duplicate: false };

/**
 * Structural view of the existing RC-04 EffectReceiptStore. There is
 * deliberately no concrete store here: memory effects are appended to the
 * same append-only store as every other runtime effect.
 */
export type EffectReceiptStoreLike = {
  append(
    receipt: MemoryEffectReceipt,
  ): EffectReceiptAppendResult | Promise<EffectReceiptAppendResult>;
};

export type MemoryEffectReceiptContext = {
  actor: MemoryEffectActor;
  effect: MemoryEffectDescriptor;
};

export type MemoryEffectReceiptInput = {
  action: MemoryEffectAction;
  factId: string;
  newFactId?: string;
  outcome: MemoryEffectOutcome;
  context: MemoryEffectReceiptContext;
  now: number;
};

export function deriveMemoryEffectIdempotencyKey(input: {
  action: MemoryEffectAction;
  factId: string;
  sessionKey: string;
  runId: string;
  toolCallId: string;
}): string {
  return [
    "runtime_memory",
    input.action,
    input.factId,
    input.sessionKey,
    input.runId,
    input.toolCallId,
  ]
    .map((part) => encodeURIComponent(part))
    .join(":");
}

function stableId(prefix: string, value: string): string {
  // FNV-1a is sufficient here: this is a stable identifier, not a security
  // primitive. It also avoids making receipt generation dependent on a crypto
  // runtime or on the receipt content/outcome.
  let hash = 0x811c9dc5;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return `${prefix}_${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

export function buildMemoryEffectReceipt(
  input: MemoryEffectReceiptInput,
): MemoryEffectReceipt {
  const idempotencyKey = deriveMemoryEffectIdempotencyKey({
    action: input.action,
    factId: input.factId,
    sessionKey: input.context.actor.sessionKey,
    runId: input.context.actor.runId,
    toolCallId: input.context.effect.toolCallId,
  });
  const proposal: MemoryEffectProposal = {
    domain: "runtime_memory",
    action: input.action,
    factId: input.factId,
    ...(input.newFactId !== undefined
      ? { newFactId: input.newFactId }
      : {}),
  };
  const stage1Context: MemoryEffectStage1Context = {
    actor: { ...input.context.actor },
    effect: { ...input.context.effect },
  };
  return {
    schemaVersion: 1,
    effectId: stableId("memory_effect", idempotencyKey),
    requestId: stableId("memory_request", idempotencyKey),
    actor: { ...input.context.actor },
    domain: "runtime_memory",
    action: input.action,
    proposal,
    stage1Context,
    outcome: input.outcome,
    idempotencyKey,
    createdAt: input.now,
  };
}

/**
 * Append through RC-04 and fail open. A missing sink, synchronous exception,
 * rejected append, or rejected promise must never change the memory operation
 * result.
 */
export function appendMemoryEffectReceipt(
  store: EffectReceiptStoreLike | undefined,
  receipt: MemoryEffectReceipt,
): void {
  if (store === undefined) return;
  try {
    const result = store.append(receipt);
    if (result instanceof Promise) {
      void result.catch(() => undefined);
    }
  } catch {
    // Receipts are observational. Their availability must not gate writes.
  }
}

export function isMemoryEffectProposalDigestOnly(
  value: unknown,
): value is MemoryEffectProposal {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const proposal = value as Record<string, unknown>;
  const allowed = new Set(["domain", "action", "factId", "newFactId"]);
  return (
    Object.keys(proposal).every((key) => allowed.has(key)) &&
    proposal.domain === "runtime_memory" &&
    (proposal.action === "memory_update" ||
      proposal.action === "memory_forget" ||
      proposal.action === "memory_strengthen") &&
    typeof proposal.factId === "string" &&
    proposal.factId.length > 0 &&
    (proposal.newFactId === undefined ||
      (typeof proposal.newFactId === "string" &&
        proposal.newFactId.length > 0))
  );
}

export function toMemoryEffectStage1Json(
  value: MemoryEffectStage1Context,
): RuntimeCoreJsonObject {
  return {
    actor: {
      sessionKey: value.actor.sessionKey,
      runId: value.actor.runId,
      attemptIndex: value.actor.attemptIndex,
      modelCallIndex: value.actor.modelCallIndex,
    },
    effect: {
      toolCallId: value.effect.toolCallId,
      toolName: value.effect.toolName,
      resource: value.effect.resource,
      action: value.effect.action,
    },
  };
}
"},{"path":"openclaw_runtime/src/runtime-core/memory-self-edit-tools.ts","content":"/**
 * Self-editing memory interface (Phase 4.4, Letta-inspired).
 *
 * Writes can optionally emit an RC-04 effect receipt. Receipt generation is
 * observational and fail-open; the memory write remains authoritative.
 */

import {
  buildEvidenceRefFixture,
  type EvidenceRef,
} from "./evidence.js";
import {
  isRuntimeMemoryRelationType,
  sanitizeRuntimeMemoryInvalidationProposal,
  type RuntimeMemoryFactRelation,
  type RuntimeMemoryInvalidationProposal,
  type RuntimeMemoryRelationType,
  type RuntimeMemorySourceEpisodeRef,
  type RuntimeMemoryTemporalFact,
} from "./memory-context.js";
import type { RuntimeMemoryStore } from "./memory-store.js";
import type { RuntimeMemoryRuntimeIntegrationPort } from "./memory-runtime-integration.js";
import {
  appendMemoryEffectReceipt,
  buildMemoryEffectReceipt,
  type EffectReceiptStoreLike,
  type MemoryEffectAction,
  type MemoryEffectOutcome,
  type MemoryEffectReceiptContext,
} from "./memory-effect-receipt.js";
import type { RuntimeCoreJsonObject } from "./types.js";

export type MemorySelfEditToolName =
  | "memory_recall"
  | "memory_update"
  | "memory_forget"
  | "memory_strengthen"
  | "memory_find_related";

export type MemorySelfEditToolResult = {
  ok: boolean;
  tool: MemorySelfEditToolName;
  message: string;
  data?: unknown;
};

export type MemorySelfEditToolContext = {
  store: RuntimeMemoryStore;
  now?: number;
  taskId?: string;
  persistence?: RuntimeMemoryRuntimeIntegrationPort;
  /** The existing RC-04 append-only effect receipt store. */
  effectReceiptStore?: EffectReceiptStoreLike;
  /** Correlation required by the memory effect idempotency contract. */
  effectContext?: MemoryEffectReceiptContext;
};

export type MemorySelfEditToolHandler = (
  args: unknown,
  context: MemorySelfEditToolContext,
) => Promise<MemorySelfEditToolResult> | MemorySelfEditToolResult;

export type MemorySelfEditTool = {
  name: MemorySelfEditToolName;
  description: string;
  parameters: Record<string, unknown>;
  execute: MemorySelfEditToolHandler;
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stringArg(args: unknown, key: string): string | undefined {
  if (!isRecord(args)) return undefined;
  const value = args[key];
  return typeof value === "string" && value.trim().length > 0
    ? value.trim()
    : undefined;
}

function numberArg(args: unknown, key: string): number | undefined {
  if (!isRecord(args)) return undefined;
  const value = args[key];
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function clampNumber(
  value: number | undefined,
  min: number,
  max: number,
  fallback: number,
): number {
  if (value === undefined) return fallback;
  return Math.min(max, Math.max(min, value));
}

function resolveNow(context: MemorySelfEditToolContext): number {
  return context.now ?? Date.now();
}

type PersistWriteOutcome = { ok: true } | { ok: false; message: string };

function persistFact(
  context: MemorySelfEditToolContext,
  fact: RuntimeMemoryTemporalFact,
): PersistWriteOutcome {
  if (context.persistence !== undefined) {
    const result = context.persistence.appendFact(fact);
    if (result.status === "persisted") return { ok: true };
    if (result.status === "rejected") {
      return { ok: false, message: result.message };
    }
    return { ok: false, message: `persistence skipped (${result.reason})` };
  }
  const result = context.store.appendFact(fact);
  return result.accepted
    ? { ok: true }
    : { ok: false, message: result.message };
}

function persistInvalidation(
  context: MemorySelfEditToolContext,
  invalidation: RuntimeMemoryInvalidationProposal,
): PersistWriteOutcome {
  if (context.persistence !== undefined) {
    const result = context.persistence.invalidateFact(invalidation);
    if (result.status === "persisted") return { ok: true };
    if (result.status === "rejected") {
      return { ok: false, message: result.message };
    }
    return { ok: false, message: `persistence skipped (${result.reason})` };
  }
  const result = context.store.invalidateFact(invalidation);
  return result.accepted
    ? { ok: true }
    : { ok: false, message: result.message };
}

function persistSupersedesRelation(
  context: MemorySelfEditToolContext,
  newFactId: string,
  oldFactId: string,
): PersistWriteOutcome {
  if (context.persistence !== undefined) {
    const result = context.persistence.persistRelation({
      sourceFactId: newFactId,
      targetFactId: oldFactId,
      relationType: "supersedes",
      confidence: 1.0,
    });
    if (result.status === "persisted") return { ok: true };
    if (result.status === "rejected") {
      return { ok: false, message: result.message };
    }
    return { ok: false, message: `persistence skipped (${result.reason})` };
  }
  context.store.appendRelation({
    sourceFactId: newFactId,
    targetFactId: oldFactId,
    relationType: "supersedes",
    confidence: 1.0,
  });
  return { ok: true };
}

function selfEditEvidenceRef(now: number): EvidenceRef {
  return buildEvidenceRefFixture({
    type: "human",
    ref: "memory_self_edit",
    label: "Memory self-edit tool",
    summary: `Self-edit action at ${now}.`,
  });
}

function cloneEvidenceRef(ref: EvidenceRef): EvidenceRef {
  const cloned: EvidenceRef = { type: ref.type, ref: ref.ref };
  if (ref.label !== undefined) cloned.label = ref.label;
  if (ref.summary !== undefined) cloned.summary = ref.summary;
  if (ref.metadata !== undefined) {
    cloned.metadata = cloneRuntimeCoreJsonObject(ref.metadata);
  }
  return cloned;
}

function cloneSourceEpisodeRef(
  ref: RuntimeMemorySourceEpisodeRef,
): RuntimeMemorySourceEpisodeRef {
  return {
    episodeId: ref.episodeId,
    ...(ref.taskId !== undefined ? { taskId: ref.taskId } : {}),
    ...(ref.kind !== undefined ? { kind: ref.kind } : {}),
    ...(ref.idempotencyKey !== undefined
      ? { idempotencyKey: ref.idempotencyKey }
      : {}),
    ...(ref.reference_time !== undefined
      ? { reference_time: ref.reference_time }
      : {}),
  };
}

function cloneRuntimeCoreJsonObject(value: unknown): RuntimeCoreJsonObject {
  return JSON.parse(JSON.stringify(value)) as RuntimeCoreJsonObject;
}

function recordMemoryEffect(
  context: MemorySelfEditToolContext,
  action: MemoryEffectAction,
  factId: string,
  outcome: MemoryEffectOutcome,
  newFactId?: string,
): void {
  if (context.effectReceiptStore === undefined || context.effectContext === undefined) {
    return;
  }
  const receipt = buildMemoryEffectReceipt({
    action,
    factId,
    ...(newFactId !== undefined ? { newFactId } : {}),
    outcome,
    context: context.effectContext,
    now: resolveNow(context),
  });
  appendMemoryEffectReceipt(context.effectReceiptStore, receipt);
}

export const memoryRecallTool: MemorySelfEditTool = {
  name: "memory_recall",
  description:
    "Search the runtime memory store for facts matching the given query. Returns matching facts with their metadata.",
  parameters: {
    type: "object",
    properties: {
      subject: { type: "string", description: "Filter by subject." },
      predicate: { type: "string", description: "Filter by predicate." },
      limit: { type: "number", description: "Maximum facts to return." },
    },
  },
  execute(args, context) {
    const subject = stringArg(args, "subject");
    const predicate = stringArg(args, "predicate");
    const limit = numberArg(args, "limit");
    const facts = context.store.queryFacts({
      ...(subject !== undefined ? { subject } : {}),
      ...(predicate !== undefined ? { predicate } : {}),
      ...(limit !== undefined ? { limit } : {}),
    });
    return {
      ok: true,
      tool: "memory_recall",
      message: `Found ${facts.length} fact(s).`,
      data: facts.map((fact) => ({
        factId: fact.factId,
        subject: fact.subject,
        predicate: fact.predicate,
        objectSummary: fact.objectSummary,
        verificationStatus: fact.verificationStatus,
        memoryType: fact.memoryType,
        valid_at: fact.valid_at,
      })),
    };
  },
};

export const memoryUpdateTool: MemorySelfEditTool = {
  name: "memory_update",
  description:
    "Update an existing fact by superseding it with new information. Creates a new fact and invalidates the old one with reason 'superseded'.",
  parameters: {
    type: "object",
    properties: {
      factId: { type: "string", description: "ID of the fact to update." },
      subject: { type: "string", description: "New subject (optional)." },
      predicate: { type: "string", description: "New predicate (optional)." },
      objectSummary: { type: "string", description: "New object summary (optional)." },
      confidence: { type: "number", description: "New confidence (optional)." },
    },
    required: ["factId"],
  },
  execute(args, context) {
    const factId = stringArg(args, "factId");
    if (factId === undefined) {
      return {
        ok: false,
        tool: "memory_update",
        message: "Missing required argument: factId.",
      };
    }

    const existing = context.store.getFactById(factId);
    if (existing === undefined) {
      recordMemoryEffect(context, "memory_update", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_update",
        message: `Fact not found: ${factId}.`,
      };
    }

    const now = resolveNow(context);
    const newFactId = `${factId}_superseded_${now}`;
    const subject = stringArg(args, "subject") ?? existing.subject;
    const predicate = stringArg(args, "predicate") ?? existing.predicate;
    const objectSummary = stringArg(args, "objectSummary") ?? existing.objectSummary;
    const confidence = numberArg(args, "confidence") ?? existing.confidence;
    const sourceEpisodeRefs: RuntimeMemorySourceEpisodeRef[] =
      existing.sourceEpisodeRefs.length > 0
        ? existing.sourceEpisodeRefs.map(cloneSourceEpisodeRef)
        : [
            {
              episodeId: "memory_self_edit",
              taskId: context.taskId ?? "memory_self_edit",
              kind: "human_confirmation",
              idempotencyKey: `memory_self_edit:${factId}:${now}`,
              reference_time: now,
            },
          ];
    const evidenceRefs: EvidenceRef[] = [
      ...existing.evidenceRefs.map(cloneEvidenceRef),
      selfEditEvidenceRef(now),
    ];
    const newFact: RuntimeMemoryTemporalFact = {
      schemaVersion: 1,
      factId: newFactId,
      ...(existing.taskId !== undefined ? { taskId: existing.taskId } : {}),
      subject,
      predicate,
      objectSummary,
      confidence,
      source: "human_confirmation",
      sourceEpisodeRefs,
      evidenceRefs,
      valid_at: now,
      reference_time: now,
      acceptedAt: now,
      verificationStatus: "human_approved",
      ...(existing.memoryType !== undefined ? { memoryType: existing.memoryType } : {}),
      promotion: {
        promotedBy: "human",
        evidenceRefs: [selfEditEvidenceRef(now)],
      },
    };

    const appendResult = persistFact(context, newFact);
    if (!appendResult.ok) {
      recordMemoryEffect(context, "memory_update", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_update",
        message: `Failed to persist new fact: ${appendResult.message}.`,
      };
    }

    const invalidation: RuntimeMemoryInvalidationProposal = {
      schemaVersion: 1,
      invalidationId: `invalidation_${factId}_${now}`,
      factId,
      reason: "superseded",
      invalid_at: now,
      reference_time: now,
      proposedBy: "human_confirmation",
      verificationStatus: "human_approved",
      sourceEpisodeRefs,
      evidenceRefs: [selfEditEvidenceRef(now)],
      replacementFactId: newFactId,
    };
    const sanitizedInvalidation =
      sanitizeRuntimeMemoryInvalidationProposal(invalidation);
    if (!sanitizedInvalidation.accepted) {
      recordMemoryEffect(
        context,
        "memory_update",
        factId,
        "unknown",
        newFactId,
      );
      return {
        ok: false,
        tool: "memory_update",
        message: `Failed to create invalidation: ${sanitizedInvalidation.message}.`,
      };
    }
    const invalidationResult = persistInvalidation(
      context,
      sanitizedInvalidation.value,
    );
    if (!invalidationResult.ok) {
      recordMemoryEffect(
        context,
        "memory_update",
        factId,
        "unknown",
        newFactId,
      );
      return {
        ok: false,
        tool: "memory_update",
        message: `Failed to persist invalidation: ${invalidationResult.message}.`,
      };
    }
    const relationResult = persistSupersedesRelation(
      context,
      newFactId,
      factId,
    );
    if (!relationResult.ok) {
      recordMemoryEffect(
        context,
        "memory_update",
        factId,
        "unknown",
        newFactId,
      );
      return {
        ok: false,
        tool: "memory_update",
        message: `Failed to persist supersedes relation: ${relationResult.message}.`,
      };
    }
    recordMemoryEffect(context, "memory_update", factId, "applied", newFactId);
    return {
      ok: true,
      tool: "memory_update",
      message: `Fact ${factId} superseded by ${newFactId}.`,
      data: {
        oldFactId: factId,
        newFactId,
        updatedFields: {
          ...(subject !== existing.subject ? { subject } : {}),
          ...(predicate !== existing.predicate ? { predicate } : {}),
          ...(objectSummary !== existing.objectSummary ? { objectSummary } : {}),
          ...(confidence !== existing.confidence ? { confidence } : {}),
        },
      },
    };
  },
};

export const memoryForgetTool: MemorySelfEditTool = {
  name: "memory_forget",
  description:
    "Actively forget (invalidate) a fact. Marks the fact as invalidated with the given reason.",
  parameters: {
    type: "object",
    properties: {
      factId: { type: "string", description: "ID of the fact to forget." },
      reason: {
        type: "string",
        enum: ["retracted", "human_rejected"],
        description: "Reason for forgetting. Defaults to 'retracted'.",
      },
    },
    required: ["factId"],
  },
  execute(args, context) {
    const factId = stringArg(args, "factId");
    if (factId === undefined) {
      return {
        ok: false,
        tool: "memory_forget",
        message: "Missing required argument: factId.",
      };
    }
    const existing = context.store.getFactById(factId);
    if (existing === undefined) {
      recordMemoryEffect(context, "memory_forget", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_forget",
        message: `Fact not found: ${factId}.`,
      };
    }
    const now = resolveNow(context);
    const reason = (stringArg(args, "reason") as
      | "retracted"
      | "human_rejected"
      | undefined) ?? "retracted";
    const sourceEpisodeRefs: RuntimeMemorySourceEpisodeRef[] =
      existing.sourceEpisodeRefs.length > 0
        ? [...existing.sourceEpisodeRefs]
        : [
            {
              episodeId: "memory_self_edit",
              taskId: context.taskId ?? "memory_self_edit",
              kind: "human_confirmation",
              idempotencyKey: `memory_self_edit_forget:${factId}:${now}`,
              reference_time: now,
            },
          ];
    const invalidation: RuntimeMemoryInvalidationProposal = {
      schemaVersion: 1,
      invalidationId: `invalidation_${factId}_${now}`,
      factId,
      reason,
      invalid_at: now,
      reference_time: now,
      proposedBy: "human_confirmation",
      verificationStatus: "human_approved",
      sourceEpisodeRefs,
      evidenceRefs: [selfEditEvidenceRef(now)],
    };
    const sanitizedInvalidation =
      sanitizeRuntimeMemoryInvalidationProposal(invalidation);
    if (!sanitizedInvalidation.accepted) {
      recordMemoryEffect(context, "memory_forget", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_forget",
        message: `Failed to create invalidation: ${sanitizedInvalidation.message}.`,
      };
    }
    const invalidationResult = persistInvalidation(
      context,
      sanitizedInvalidation.value,
    );
    if (!invalidationResult.ok) {
      recordMemoryEffect(context, "memory_forget", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_forget",
        message: `Failed to persist invalidation: ${invalidationResult.message}.`,
      };
    }
    recordMemoryEffect(context, "memory_forget", factId, "applied");
    return {
      ok: true,
      tool: "memory_forget",
      message: `Fact ${factId} forgotten (reason: ${reason}).`,
      data: { factId, reason },
    };
  },
};

export const memoryStrengthenTool: MemorySelfEditTool = {
  name: "memory_strengthen",
  description:
    "Strengthen a fact's retention signal by recording a usage access. This boosts the fact's eviction score, making it less likely to be evicted under capacity pressure.",
  parameters: {
    type: "object",
    properties: {
      factId: { type: "string", description: "ID of the fact to strengthen." },
    },
    required: ["factId"],
  },
  execute(args, context) {
    const factId = stringArg(args, "factId");
    if (factId === undefined) {
      return {
        ok: false,
        tool: "memory_strengthen",
        message: "Missing required argument: factId.",
      };
    }
    const existing = context.store.getFactById(factId);
    if (existing === undefined) {
      recordMemoryEffect(context, "memory_strengthen", factId, "not_applied");
      return {
        ok: false,
        tool: "memory_strengthen",
        message: `Fact not found: ${factId}.`,
      };
    }
    if (context.persistence !== undefined) {
      const accessResult = context.persistence.recordFactAccess(factId);
      if (accessResult.status !== "persisted") {
        recordMemoryEffect(context, "memory_strengthen", factId, "not_applied");
        const message = accessResult.status === "rejected"
          ? accessResult.message
          : `persistence skipped (${accessResult.reason})`;
        return {
          ok: false,
          tool: "memory_strengthen",
          message: `Failed to persist usage access: ${message}`,
        };
      }
      context.store.recordFactAccess(factId);
      recordMemoryEffect(context, "memory_strengthen", factId, "applied");
      return {
        ok: true,
        tool: "memory_strengthen",
        message: `Fact ${factId} strengthened (usage count: ${accessResult.accessCount}).`,
        data: { factId, usageCount: accessResult.accessCount },
      };
    }
    context.store.recordFactAccess(factId);
    const usageStats = context.store.getUsageStats();
    const stat = usageStats.find((item) => item.factId === factId);
    const newCount = stat?.count ?? 0;
    recordMemoryEffect(context, "memory_strengthen", factId, "applied");
    return {
      ok: true,
      tool: "memory_strengthen",
      message: `Fact ${factId} strengthened (usage count: ${newCount}).`,
      data: { factId, usageCount: newCount },
    };
  },
};

export const memoryFindRelatedTool: MemorySelfEditTool = {
  name: "memory_find_related",
  description:
    "Find facts related to a given fact via the relation chain (1-hop or 2-hop). Useful for exploring memory connections such as superseded facts, contradictions, or semantically related facts.",
  parameters: {
    type: "object",
    properties: {
      factId: { type: "string", description: "The fact ID to find relations for." },
      relationType: {
        type: "string",
        enum: ["supersedes", "contradicts", "related_to"],
        description: "Optional filter by relation type.",
      },
      hops: {
        type: "number",
        minimum: 1,
        maximum: 2,
        default: 1,
        description: "Number of hops (1 or 2).",
      },
      limit: {
        type: "number",
        minimum: 1,
        maximum: 20,
        default: 10,
        description: "Maximum number of related facts to return.",
      },
    },
    required: ["factId"],
  },
  execute(args, context) {
    const factId = stringArg(args, "factId");
    if (factId === undefined) {
      return {
        ok: false,
        tool: "memory_find_related",
        message: "Missing required argument: factId.",
      };
    }
    const rawRelationType = stringArg(args, "relationType");
    const relationType: RuntimeMemoryRelationType | undefined =
      rawRelationType !== undefined && isRuntimeMemoryRelationType(rawRelationType)
        ? rawRelationType
        : undefined;
    const hops = clampNumber(numberArg(args, "hops"), 1, 2, 1);
    const limit = clampNumber(numberArg(args, "limit"), 1, 20, 10);
    const sourceFact = context.store.getFactById(factId);
    if (sourceFact === undefined) {
      return {
        ok: false,
        tool: "memory_find_related",
        message: `Fact not found: ${factId}.`,
      };
    }
    const visited = new Set<string>([factId]);
    const collectedRelations: RuntimeMemoryFactRelation[] = [];
    let frontier = [factId];
    for (let hop = 0; hop < hops; hop += 1) {
      const nextFrontier: string[] = [];
      for (const currentId of frontier) {
        const relations = [
          ...context.store.queryRelations(currentId, relationType),
          ...context.store.queryReverseRelations(currentId, relationType),
        ];
        for (const relation of relations) {
          collectedRelations.push(relation);
          const otherId = relation.sourceFactId === currentId
            ? relation.targetFactId
            : relation.targetFactId === currentId
              ? relation.sourceFactId
              : undefined;
          if (otherId === undefined || visited.has(otherId)) continue;
          visited.add(otherId);
          nextFrontier.push(otherId);
        }
      }
      frontier = nextFrontier;
    }
    const facts = [...visited]
      .filter((id) => id !== factId)
      .slice(0, limit)
      .map((id) => context.store.getFactById(id))
      .filter((fact): fact is NonNullable<typeof fact> => fact !== undefined);
    const seen = new Set<string>();
    const relations = collectedRelations.filter((relation) => {
      if (seen.has(relation.relationId)) return false;
      seen.add(relation.relationId);
      return true;
    });
    return {
      ok: true,
      tool: "memory_find_related",
      message: `Found ${facts.length} related fact(s) within ${hops} hop(s).`,
      data: {
        facts: facts.map((fact) => ({
          factId: fact.factId,
          subject: fact.subject,
          predicate: fact.predicate,
          objectSummary: fact.objectSummary,
          verificationStatus: fact.verificationStatus,
          memoryType: fact.memoryType,
          valid_at: fact.valid_at,
        })),
        relations: relations.map((relation) => ({
          relationId: relation.relationId,
          sourceFactId: relation.sourceFactId,
          targetFactId: relation.targetFactId,
          relationType: relation.relationType,
          confidence: relation.confidence,
        })),
        hops,
      },
    };
  },
};

export const MEMORY_SELF_EDIT_TOOLS: readonly MemorySelfEditTool[] = [
  memoryRecallTool,
  memoryUpdateTool,
  memoryForgetTool,
  memoryStrengthenTool,
  memoryFindRelatedTool,
];

export function getMemorySelfEditTool(
  name: MemorySelfEditToolName,
): MemorySelfEditTool | undefined {
  return MEMORY_SELF_EDIT_TOOLS.find((tool) => tool.name === name);
}

export function executeMemorySelfEditTool(
  name: MemorySelfEditToolName,
  args: unknown,
  context: MemorySelfEditToolContext,
): Promise<MemorySelfEditToolResult> | MemorySelfEditToolResult {
  const tool = getMemorySelfEditTool(name);
  if (tool === undefined) {
    return Promise.resolve({
      ok: false,
      tool: name,
      message: `Unknown tool: ${name}.`,
    });
  }
  return tool.execute(args, context);
}
"},{"path":"harness/specs/tasks/harness-gap-memory-effect-receipt.md","content":"# S06 — Runtime memory self-edit effect receipts

## Objective

Runtime memory self-edit writes (`memory_update`, `memory_forget`, and
`memory_strengthen`) use the existing RC-04 `EffectReceiptStore`. No second effect
store, migration, or parallel persistence model is introduced.

## Contract

- A receipt is appended for each write attempt when receipt context is supplied.
- The proposal is digest-only and contains only:
  `domain`, `action`, `factId`, and optional `newFactId`.
  It must never contain subject, predicate, object text, raw tool arguments, or
  any other memory body.
- `stage1Context.actor` contains `sessionKey`, `runId`, `attemptIndex`, and
  `modelCallIndex`.
- `stage1Context.effect` contains `toolCallId`, `toolName`, `resource`, and
  `action`.
- Every receipt exposes `effectId`, `requestId`, and actor identity.
- The idempotency key is derived only from the write intent:
  `action + factId + sessionKey + runId + toolCallId`.
  It does not include the write outcome or memory body.
- The RC-04 store remains responsible for unique idempotency enforcement,
  identical-content duplicate detection, and content-conflict detection.
  Replaying the same intent must produce zero duplicate effects.

## Outcome mapping

| Situation | Outcome |
| --- | --- |
| The complete write succeeds | `applied` |
| Failure occurs before any durable write | `not_applied` |
| Some part was written and a later step failed | `unknown` |

In particular, `memory_update` is `unknown` if the replacement fact was
appended but invalidation or supersession relation persistence failed.

## Fail-open behavior

A missing receipt sink, a synchronous sink exception, or an asynchronous sink
rejection must not fail or prevent a memory write. Receipt observability must not
become a second transaction boundary.

## Verification

- Targeted tests cover applied, not-applied, and unknown outcomes.
- A same-intent replay reports a duplicate and creates zero duplicate effects.
- Receipts are inspected to prove that memory text is absent.
- Runtime-core type checking and scoped lint pass.
- Harness validation and dry-run pass.
- Comms replay and compare pass.
- Credential scan reports zero matches.
- `SHA256SUMS` can be read and verified.
"},{"path":"docs/dev/harness-gap-closure/s06-memory-effect-receipt.md","content":"# S06 closure: runtime memory effect receipts

## Design

Memory self-edit tools now have an optional `effectReceiptStore` and an optional
`effectContext`. The store is the existing RC-04 append-only effect receipt
store; the implementation does not own or persist a second receipt collection.
The memory effect module supplies only the RC-04-shaped receipt envelope and
calls the supplied store's `append` method.

The effect context is supplied by the runtime caller:

```ts
{
  actor: {
    sessionKey,
    runId,
    attemptIndex,
    modelCallIndex,
  },
  effect: {
    toolCallId,
    toolName,
    resource,
    action,
  },
}
```

The receipt proposal is intentionally restricted to an identifier envelope:

```ts
{
  domain: "runtime_memory",
  action: "memory_update" | "memory_forget" | "memory_strengthen",
  factId,
  newFactId?, // update only
}
```

No subject, predicate, object summary, raw arguments, or serialized memory
fact is copied into the receipt.

## Idempotency and outcome semantics

The idempotency key is derived from the intent only. It consists of the action,
fact ID, session key, run ID, and tool call ID. Outcome and memory content are
excluded. The RC-04 store therefore recognizes a replay as identical content
and reports a duplicate without adding another effect.

Write results map to receipt outcomes as follows:

- `applied`: every required write completed.
- `not_applied`: the operation failed before a durable write.
- `unknown`: at least one write completed, but a later required write failed.

For update, appending the replacement fact is the boundary between
`not_applied` and `unknown`. Failure to persist invalidation or the supersedes
relation after that append is explicitly `unknown`.

## Operational safety

Receipt emission is fail-open. Missing sinks, thrown errors, and rejected
promises are ignored from the memory operation's perspective. The memory write
result is not changed and no receipt error is surfaced as a write failure.

## Closure evidence

The implementation and targeted tests establish:

1. RC-04 store reuse without a second store.
2. Digest-only proposals with no memory body.
3. Actor and effect correlation in stage-one context.
4. Intent-derived idempotency and duplicate replay behavior.
5. Honest applied/not-applied/unknown mapping.
6. Fail-open receipt behavior.

The task specification in `harness/specs/tasks/harness-gap-memory-effect-receipt.md`
contains the acceptance and validation checklist.
"}]}

